def solve_game(N):
    """
    Determines if the starting position 1 leads to a win for A (Type A) or B (Type B)
    when the target is N.
    """
    if N == 1:
        return True

    Win = [False] * (N + 1)

    for n in range(N - 1, 0, -1):
        can_win = False

        moves = []
        m1 = n + 1
        m2 = 2 * n

        if m1 <= N:
            moves.append(m1)
        if m2 <= N:
            moves.append(m2)

        for m in moves:
            if m == N:
                can_win = True
                break
            elif m < N:
                if not Win[m]:
                    can_win = True
                    break

        Win[n] = can_win

    return Win[1]

# Search starting from N=401
N_start = 401
limit = 500 # Set a practical limit for searching

for N in range(N_start, limit + 1):
    is_type_A = solve_game(N)

    if not is_type_A:
        # Found the least N > 400 that is Type B
        print(f"Found it! N = {N} is Type B.")
        break
else:
    print(f"Did not find a Type B number up to N={limit}.")

